files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #2a2a2a;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #6b6b6b;
  --vt-on-deep: #ffffff;
  --vt-accent: #fb5849;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #c43a2f;
  --vt-accent-on-deep: #fb5849;
  --vt-line: #ead9d6;
  color: var(--vt-ink);
  background: var(--vt-surface);
  font-family: 'Fira Sans', Arial, sans-serif;
  line-height: 1.6;
}

.root, .root * {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-family: 'Fraunces', Georgia, serif;
  line-height: 1.2;
}

.root :where(p) {
  margin: 0;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  min-height: 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
}

.logo {
  display: inline-flex;
  align-items: center;
}

.brand {
  display: inline-flex;
  align-items: center;
  font-family: 'Fraunces', Georgia, serif;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--vt-ink);
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 28px;
}

.navLinks a {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: var(--vt-ink);
  transition: color 0.2s ease;
}

.navLinks a:hover,
.navLinks a:focus-visible {
  color: var(--vt-accent-ink);
}

.hero {
  display: grid;
  grid-template-columns: clamp(320px, 38%, 520px) 1fr;
  min-height: 680px;
  background: var(--vt-surface-deep);
}

.heroPanel {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 32px;
}

.heroInner {
  max-width: 360px;
  text-align: center;
}

.heroBrand {
  display: block;
  color: var(--vt-on-accent);
  font-family: 'Fraunces', Georgia, serif;
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 8px;
}

.heroTitle {
  font-size: clamp(40px, 5vw, 58px);
  color: var(--vt-on-accent);
  font-weight: 700;
}

.heroKicker {
  margin-top: 12px;
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--vt-on-accent);
}

.heroButton {
  display: inline-block;
  margin-top: 28px;
  padding: 12px 28px;
  background: var(--vt-surface);
  color: var(--vt-accent-ink);
  border-radius: 4px;
  font-size: 13px;
  font-weight: 600;
  transition: opacity 0.2s ease;
}

.heroButton:hover {
  opacity: 0.9;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  max-height: 680px;
  scrollbar-width: none;
}

.heroSlides::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  min-width: 100%;
  height: 100%;
  scroll-snap-align: start;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.about {
  max-width: 1200px;
  margin: 0 auto;
  padding: 120px 24px 100px;
}

.aboutGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.eyebrow {
  position: relative;
  padding-left: 40px;
  color: var(--vt-accent-ink);
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.eyebrow::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 30px;
  height: 1px;
  background: var(--vt-accent-ink);
  transform: translateY(-50%);
}

.title {
  margin: 16px 0 24px;
  font-size: clamp(28px, 3.5vw, 38px);
  line-height: 1.25;
  color: var(--vt-ink);
}

.paragraph {
  margin-bottom: 16px;
  color: var(--vt-ink-soft);
  font-size: 15px;
  line-height: 1.7;
}

.aboutVisual {
  position: relative;
}

.aboutMain {
  border-radius: 8px;
  overflow: hidden;
}

.aboutMain img {
  width: 100%;
  height: 460px;
  object-fit: cover;
}

.aboutThumbs {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: -56px;
  padding-right: 24px;
}

.aboutThumbs img {
  width: 100%;
  height: 120px;
  object-fit: cover;
  border: 4px solid var(--vt-surface);
  border-radius: 6px;
}

.menu {
  background: var(--vt-surface-2);
  padding: 120px 24px;
}

.sectionHead {
  max-width: 1200px;
  margin: 0 auto 64px;
}

.menuRow {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.menuCard {
  position: relative;
  background: var(--vt-surface);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 12px 28px color-mix(in srgb, var(--vt-surface-deep) 10%, transparent);
}

.menuImage {
  width: 100%;
  height: 260px;
  object-fit: cover;
}

.menuNum {
  position: absolute;
  top: 14px;
  left: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 4px;
  font-size: 18px;
  font-weight: 700;
}

.menuBody {
  padding: 24px 20px 28px;
}

.menuTitle {
  font-size: 22px;
  color: var(--vt-ink);
  margin-bottom: 8px;
}

.menuDesc {
  font-size: 14px;
  color: var(--vt-ink-soft);
  line-height: 1.6;
}

.menuLink {
  display: inline-block;
  margin-top: 16px;
  font-size: 13px;
  font-weight: 600;
  color: var(--vt-accent-ink);
}

.menuLink:hover {
  color: var(--vt-accent-ink);
  text-decoration: underline;
}

.gallery {
  max-width: 1200px;
  margin: 0 auto;
  padding: 120px 24px;
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.galleryItem {
  position: relative;
  margin: 0;
  border-radius: 8px;
  overflow: hidden;
}

.galleryItem img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.galleryItem:hover img {
  transform: scale(1.03);
}

.galleryItem figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 18px 16px;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  font-weight: 600;
}

.contact {
  background: var(--vt-surface-deep);
  padding: 120px 24px;
}

.contactInner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.contactInfo .eyebrow {
  color: var(--vt-accent-on-deep);
}

.contactInfo .eyebrow::before {
  background: var(--vt-accent-on-deep);
}

.contactInfo .title {
  color: var(--vt-on-deep);
}

.contactCard {
  background: var(--vt-surface);
  border-radius: 8px;
  padding: 48px;
  box-shadow: 0 24px 60px color-mix(in srgb, var(--vt-surface-deep) 35%, transparent);
}

.contactCardTitle {
  font-size: 30px;
  color: var(--vt-ink);
  margin-bottom: 12px;
}

.contactCardText {
  color: var(--vt-ink-soft);
  line-height: 1.7;
  margin-bottom: 24px;
}

.footer {
  background: var(--vt-accent);
  padding: 48px 24px;
  color: var(--vt-on-accent);
}

.footerIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.footerBrand {
  color: var(--vt-on-accent);
  font-family: 'Fraunces', Georgia, serif;
  font-weight: 700;
  font-size: 28px;
}

.footerText {
  color: var(--vt-on-accent);
  font-size: 14px;
}

@media (max-width: 992px) {
  .navIn {
    min-height: auto;
    flex-direction: column;
    padding: 16px 24px;
    gap: 12px;
  }

  .hero {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .heroPanel {
    min-height: 380px;
  }

  .heroSlides {
    max-height: 420px;
  }

  .aboutGrid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .aboutMain img {
    height: 380px;
  }

  .menuRow {
    grid-template-columns: repeat(2, 1fr);
  }

  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .contactInner {
    grid-template-columns: 1fr;
  }

  .footerIn {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 600px) {
  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
    gap: 12px;
  }

  .heroPanel {
    padding: 40px 20px;
    min-height: 360px;
  }

  .heroTitle {
    font-size: 38px;
  }

  .aboutThumbs {
    padding-right: 0;
  }

  .menuRow {
    grid-template-columns: 1fr;
  }

  .galleryGrid {
    grid-template-columns: 1fr;
  }
}
